export DEBIAN_FRONTEND=noninteractive; command -v sshd >/dev/null 2>&1 || { echo '[BSL] installing openssh-server...'; apt-get update 2>&1 | tail -1; apt-get install -y --no-install-recommends openssh-server 2>&1 | tail -2; }; mkdir -p /run/sshd /etc/ssh/sshd_config.d; getent passwd sshd >/dev/null || useradd -r -M -d /run/sshd -s /usr/sbin/nologin sshd; printf 'Port 2222\nPasswordAuthentication yes\nUsePAM no\nPermitRootLogin no\nMaxAuthTries 3\nX11Forwarding no\n' > /etc/ssh/sshd_config.d/breadstick.conf; ssh-keygen -A 2>&1 | tail -1; systemctl disable --now ssh.socket ssh.service sshd.socket sshd.service >/dev/null 2>&1 || true; command -v sshd
